properties.property:
[
{
   "text": "Жизнеописания магов, о которых ты никогда не слышал. По первым страницам трудно понять, чем они прославились.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "Дневники солдат из разных армий. Сопоставив записи за один день, можно восстановить ход целого сражения.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "Караванные накладные. Несколько товаров обведены, а на полях видны чужие пометки.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "«О неотложной угрозе всем цивилизованным народам». За пышным названием скрывается донесение разведчика.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null,
      "text": "Разведчик нашёл улей щепок больше крупнейшего города Шандалара. К донесению приложена карта.",
      "loctext": null,
      "options": [
         {"name": "Отложить донесение", "locname": null},
         {
            "name": "А вдруг улей всё ещё там? Записать координаты.",
            "locname": null,
            "action": [{"deleteMapObject":-1}, {"issueQuest":34}],
            "text": "Ты отмечаешь на своей карте улей Скеп. Сюда можно прийти позже.",
            "loctext": null,
            "options": [{"name": "Дальше", "locname": null}]
         }
      ]
   }]
}   
]

[
{
   "text": "Жизнеописания магов, о которых ты никогда не слышал. По первым страницам трудно понять, чем они прославились.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "Копии чертежей гоблинских изобретений. Переписчик каждому выставил оценку.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "«Как выдрессировать барсука». Автор — Зелёный Рукав. Хочется увидеть хотя бы один его урок.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "«Жар Пардика». Любовный роман о двух магах, между которыми в буквальном смысле пробежала искра.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "«Обычные обличья мимиков». Книгу стоило бы прочесть, если бы она не пыталась укусить тебя за палец.",
   "loctext": null,
   "options": [{
      "name": "Дальше",
      "locname": null, "action": [{"battleWithActorID":49}]}]
}
]

[
    {
        "condition": [
            {
                "getQuestFlag": {
                    "key": "exploreShand1",
                    "op": "=",
                    "val": 4
                }
            },
            {
                "checkQuestFlag": "foundLibraryOfVarsilResearch",
                "not": true
            }
        ],
        "text": "«Образец 35 отрицает прежние призывы. На седьмой стадии недомогание слабее. Ещё до призыва образца 36 он, кажется, уже ждёт опасности…»",
        "loctext": null,
        "options": [
            {
                "name": "Дальше",
                "locname": null,
                "action": [
                    {
                        "setQuestFlag": {
                            "key": "foundLibraryOfVarsilResearch",
                            "val": 1
                        }
                    }
                ],
                "text": "Похоже, именно эти записи нужны Доновану.",
                "loctext": null,
                "options": [
                    {
                        "condition": [
                            {
                                "checkQuestFlag": "defeatedLibraryOfVarsilBoss",
                                "not": true
                            }
                        ],
                        "name": "Забрать документы",
                        "locname": null,
                        "text": "Записи для Донована у тебя. Можно осмотреть другие полки или вернуться тем же путём.",
                        "loctext": null,
                        "options": [
                            {
                                "name": "Дальше",
                                "locname": null
                            }
                        ]
                    },
                    {
                        "condition": [
                            {
                                "checkQuestFlag": "defeatedLibraryOfVarsilBoss"
                            }
                        ],
                        "name": "Забрать документы",
                        "locname": null,
                        "text": "Огромная машина наверху уже побеждена. Здесь дело закончено.",
                        "loctext": null,
                        "options": [
                            {
                                "name": "Дальше",
                                "locname": null
                            }
                        ]
                    }
                ]
            }
        ]
    }
]
